(()=>{'use strict';if(window.DEMO_PAGE?.id!=='BL-04-01')return;const A=window.WO_TOOLTIP_ASSETS;let tip,timer,closeTimer,anchor;function close(){clearTimeout(timer);clearTimeout(closeTimer);timer=null;tip?.remove();tip=null;anchor?.removeAttribute('aria-describedby');anchor=null;}function show(button){close();if(!button.isConnected)return;anchor=button;const box=document.createElement('template');box.innerHTML=A.html;tip=box.content.firstElementChild;tip.style.cssText='position:fixed;inset:auto;z-index:1030;pointer-events:auto;box-sizing:border-box;--antd-arrow-background-color:rgba(0,0,0,.7)';for(const[k,v]of Object.entries(A.font))tip.querySelector('.the-popover-content').style.setProperty(k,v);tip.querySelector('.the-popover-content').textContent=button.textContent;const inner=tip.querySelector('[role=tooltip]');inner.id='wo-number-full-value';button.setAttribute('aria-describedby',inner.id);document.body.append(tip);const r=button.closest('.demo-wo-number').getBoundingClientRect(),cell=button.closest('.kodo-art-table-cell').getBoundingClientRect(),width=tip.getBoundingClientRect().width,height=tip.getBoundingClientRect().height;tip.style.left=Math.max(4,Math.min(innerWidth-width-4,Math.floor(r.x+r.width/2-width/2)))+'px';tip.style.top=Math.floor(cell.top-height-5)+'px';const arrow=tip.querySelector('.kodo-new-popover-arrow');arrow.style.cssText='position:absolute;bottom:0;left:50%';if(cell.top-height-5<0){tip.classList.replace('kodo-new-popover-placement-top','kodo-new-popover-placement-bottom');tip.style.top=cell.bottom+5+'px';arrow.style.cssText='position:absolute;top:0;left:50%';}}
function wire(){document.querySelectorAll('.demo-wo-number-value[title]').forEach(e=>e.removeAttribute('title'));}wire();new MutationObserver(wire).observe(document.querySelector('.kodo-art-table-tbody'),{childList:true,subtree:true});document.addEventListener('pointerover',e=>{const b=e.target.closest('.demo-wo-number-value');if(b){clearTimeout(closeTimer);if(anchor===b||timer)return;timer=setTimeout(()=>show(b),100);}else if(tip?.contains(e.target))clearTimeout(closeTimer);else{clearTimeout(timer);timer=null;clearTimeout(closeTimer);closeTimer=setTimeout(close,100);}},true);document.addEventListener('focusin',e=>{const b=e.target.closest('.demo-wo-number-value');if(b)show(b);},true);document.addEventListener('focusout',close,true);window.addEventListener('pointerdown',e=>{if(!tip?.contains(e.target))close();},true);window.addEventListener('keydown',e=>{if(e.key==='Escape')close();},true);window.addEventListener('scroll',e=>{if(!(e.target instanceof Node)||!tip?.contains(e.target))close();},true);document.documentElement.dataset.demoNumberTooltipReady='1';})();

